package dev.gbppimentel.zzz;
public final class CompanionLifecycleTest{public static void main(String[] args){int n=0;CompanionLifecycle p=new CompanionLifecycle();if(p.observe(0,true,false,true)||p.observe(5000,true,false,true))throw new AssertionError("Manual launch must keep its waiting state");n++;if(!CompanionLifecycle.isHomeReason("homekey")||!CompanionLifecycle.isHomeReason("home"))throw new AssertionError("Physical/vendor Home reasons");n++;if(CompanionLifecycle.isHomeReason("recentapps")||CompanionLifecycle.isHomeReason("assist")||CompanionLifecycle.isHomeReason(null))throw new AssertionError("Only Home is a suspend signal");n++;p.observe(6000,true,true,false);if(p.observe(6100,true,false,true)||!p.observe(6800,true,false,true))throw new AssertionError("Paired companion must suspend after the game returns Home");n++;p=new CompanionLifecycle();p.observe(0,true,true,false);p.observe(100,true,false,true);p.observe(200,true,true,false);if(p.observe(1000,true,true,false))throw new AssertionError("Transient launcher flash must not suspend");n++;if(p.observe(2000,true,false,false)||p.observe(5000,true,false,false))throw new AssertionError("Settings/login overlays are not Home");n++;p.observe(6000,true,false,true);if(p.observe(8000,false,false,true))throw new AssertionError("Stale/failed visibility query must not suspend");n++;if(p.observe(8100,true,false,true)||!p.observe(8800,true,false,true))throw new AssertionError("Require fresh consecutive launcher observations");n++;p.resume();if(p.observe(20000,true,false,true)||p.observe(25000,true,false,true))throw new AssertionError("Resume cannot immediately resuspend before the game has returned");n++;System.out.println(n+" lifecycle checks passed");}}
